using System;
using System.ComponentModel.DataAnnotations;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

public sealed record BlogRequest([property: Required] string Name);
public sealed record BlogResponse(Guid Id, string Name);

public sealed record PostRequest([property: Required] string Title);
public sealed record PostResponse(Guid Id, Guid BlogId, string Title);

[ApiController]
[Route("api/blogs")]
public class BlogsController(AppDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<BlogResponse>> Create(BlogRequest request, CancellationToken ct)
    {
        var blog = new Blog { Id = Guid.NewGuid(), Name = request.Name };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id = blog.Id }, new BlogResponse(blog.Id, blog.Name));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        if (blog is null) return NotFound();
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<BlogResponse>> Update(Guid id, BlogRequest request, CancellationToken ct)
    {
        var blog = await db.Blogs.FindAsync([id], ct);
        if (blog is null) return NotFound();
        blog.Name = request.Name;
        await db.SaveChangesAsync(ct);
        return Ok(new BlogResponse(blog.Id, blog.Name));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.FindAsync([id], ct);
        if (blog is null) return NotFound();
        db.Blogs.Remove(blog);
        await db.SaveChangesAsync(ct);
        return NoContent();
    }
}

