using System;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;

namespace BlogApi;

[ApiController]
[Route("api/blogs")]
public class BlogsController(BlogDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<IActionResult> Create(BlogInput input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Name)) return BadRequest("name is required");
        var id = input.Id ?? Guid.NewGuid();
        var existing = await db.Blogs.FindAsync([id], ct);
        if (existing is not null)
            return existing.Name == input.Name ? Ok(Dto(existing)) : Conflict();

        var blog = new Blog { Id = id, Name = input.Name, ConcurrencyStamp = Guid.NewGuid() };
        db.Blogs.Add(blog);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id }, Dto(blog));
    }

    [HttpGet("{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await db.Blogs.AsNoTracking().FirstOrDefaultAsync(b => b.Id == id, ct);
        return blog is null ? NotFound() : Ok(Dto(blog));
    }

    [HttpPut("{id:guid}")]
    public async Task<IActionResult> Update(Guid id, BlogInput input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Name)) return BadRequest("name is required");
        var blog = await db.Blogs.FindAsync([id], ct);
        if (blog is null) return NotFound();

        blog.Name = input.Name;
        blog.ConcurrencyStamp = Guid.NewGuid();
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return Conflict(); }
        return Ok(Dto(blog));
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        await db.Blogs.Where(b => b.Id == id).ExecuteDeleteAsync(ct);
        return NoContent();
    }

    private static BlogDto Dto(Blog b) => new(b.Id, b.Name);
}

[ApiController]
[Route("api")]
public class PostsController(BlogDbContext db) : ControllerBase
{
    [HttpPost("blogs/{blogId:guid}/posts")]
    public async Task<IActionResult> Create(Guid blogId, PostInput input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Title)) return BadRequest("title is required");
        if (!await db.Blogs.AnyAsync(b => b.Id == blogId, ct)) return NotFound();

        var id = input.Id ?? Guid.NewGuid();
        var existing = await db.Posts.FindAsync([id], ct);
        if (existing is not null)
            return existing.BlogId == blogId && existing.Title == input.Title ? Ok(Dto(existing)) : Conflict();

        var post = new Post { Id = id, BlogId = blogId, Title = input.Title, ConcurrencyStamp = Guid.NewGuid() };
        db.Posts.Add(post);
        await db.SaveChangesAsync(ct);
        return CreatedAtAction(nameof(Get), new { id }, Dto(post));
    }

    [HttpGet("posts/{id:guid}")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var viewed = await db.Posts.Where(p => p.Id == id)
            .ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        if (viewed == 0) return NotFound();

        var post = await db.Posts.AsNoTracking().FirstOrDefaultAsync(p => p.Id == id, ct);
        return post is null ? NotFound() : Ok(Dto(post));
    }

    [HttpPut("posts/{id:guid}")]
    public async Task<IActionResult> Update(Guid id, PostInput input, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(input.Title)) return BadRequest("title is required");
        var post = await db.Posts.FindAsync([id], ct);
        if (post is null) return NotFound();

        post.Title = input.Title;
        post.ConcurrencyStamp = Guid.NewGuid();
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return Conflict(); }
        return Ok(Dto(post));
    }

    [HttpDelete("posts/{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
