using System;
using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using Microsoft.EntityFrameworkCore;

public sealed class Blog
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public string Name { get; set; } = "";
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTimeOffset? DeletedAt { get; set; }
}

public sealed class Post
{
    public int Id { get; set; }
    public Guid PublicId { get; set; }
    public int BlogId { get; set; }
    public Guid BlogPublicId { get; set; }
    public string Title { get; set; } = "";
    public int Views { get; set; }
    public string ETag { get; set; } = "";
    public string CreateHash { get; set; } = "";
    public DateTimeOffset? DeletedAt { get; set; }
}

public sealed class BlogDto
{
    public Guid Id { get; set; }
    public string? Name { get; set; }
}

public sealed class PostDto
{
    public Guid Id { get; set; }
    public Guid BlogId { get; set; }
    public string? Title { get; set; }
}

public sealed record BlogRepr(Guid Id, string Name);

public sealed record PostRepr(Guid Id, Guid BlogId, string Title);

public static class Canon
{
    static readonly JsonSerializerOptions Options = new(JsonSerializerDefaults.Web)
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    public static string Normalize(string value) => value.Normalize(NormalizationForm.FormC);

    public static string ETag<T>(T representation)
    {
        var hash = SHA256.HashData(Encoding.UTF8.GetBytes(JsonSerializer.Serialize(representation, Options)));
        return "\"" + Convert.ToBase64String(hash).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }
}

public sealed class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Blog> Blogs => Set<Blog>();
    public DbSet<Post> Posts => Set<Post>();

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(e =>
        {
            e.HasKey(b => b.Id);
            e.HasIndex(b => b.PublicId).IsUnique();
            e.Property(b => b.Name).IsRequired();
            e.Property(b => b.ETag).IsRequired().IsConcurrencyToken();
            e.Property(b => b.CreateHash).IsRequired();
            e.HasQueryFilter(b => b.DeletedAt == null);
        });

        modelBuilder.Entity<Post>(e =>
        {
            e.HasKey(p => p.Id);
            e.HasIndex(p => p.PublicId).IsUnique();
            e.Property(p => p.Title).IsRequired();
            e.Property(p => p.ETag).IsRequired().IsConcurrencyToken();
            e.Property(p => p.CreateHash).IsRequired();
            e.HasOne<Blog>().WithMany().HasForeignKey(p => p.BlogId).OnDelete(DeleteBehavior.Restrict);
            e.HasQueryFilter(p => p.DeletedAt == null);
        });
    }
}
