```csharp
using System;
using System.ComponentModel.DataAnnotations;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public abstract class ApiBaseController : ControllerBase
{
    protected static bool Matches(string header, string etag) =>
        header.Split(',').Select(t => t.Trim()).Any(t => t == "*" || t == etag);

    protected IActionResult Error(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentTypes = { "application/problem+json" }
        };

    protected IActionResult PreconditionFailed(string etag)
    {
        Response.Headers.ETag = etag;
        return Error(StatusCodes.Status412PreconditionFailed, "Precondition failed");
    }

    protected static bool IsUniqueViolation(DbUpdateException ex) =>
        ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 };
}

[Route("api/blogs")]
public sealed class BlogsController(AppDbContext db) : ApiBaseController
{
    [HttpPost]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] BlogDto? dto, CancellationToken ct)
    {
        if (dto is null || dto.Id == Guid.Empty || string.IsNullOrWhiteSpace(dto.Name)) return Error(400, "Invalid blog");
        var name = Canon.Normalize(dto.Name);
        var etag = Canon.ETag(new BlogRepr(dto.Id, name));
        var blog = new Blog { PublicId = dto.Id, Name = name, ETag = etag, CreateHash = etag };
        db.Blogs.Add(blog);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstAsync(b => b.PublicId == dto.Id, ct);
            if (existing.DeletedAt is not null) return Error(410, "Gone");
            if (existing.CreateHash != etag) return Error(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToDto(existing));
        }
        Response.Headers.ETag = etag;
        return Created($"/api/blogs/{blog.PublicId}", ToDto(blog));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(BlogDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var blog = await FindBlog(id, ct);
        if (blog is null) return Error(404, "Not found");
        if (blog.DeletedAt is not null) return Error(410, "Gone");
        Response.Headers.ETag = blog.ETag;
        if (Matches(Request.Headers["If-None-Match"].ToString(), blog.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToDto(blog));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] BlogDto? dto, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (dto is null || dto.Id != id || string.IsNullOrWhiteSpace(dto.Name)) return Error(400, "Invalid blog");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Error(428, "If-Match is required");
        var blog = await FindBlog(id, ct);
        if (blog is null) return Error(404, "Not found");
        if (blog.DeletedAt is not null) return Error(410, "Gone");
        var name = Canon.Normalize(dto.Name);
        var etag = Canon.ETag(new BlogRepr(id, name));
        if (blog.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (!Matches(ifMatch, blog.ETag)) return PreconditionFailed(blog.ETag);
        blog.Name = name;
        blog.ETag = etag;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return PreconditionFailed(await CurrentETag(id, ct)); }
        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Error(428, "If-Match is required");
        var blog = await FindBlog(id, ct);
        if (blog is null || blog.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, blog.ETag)) return PreconditionFailed(blog.ETag);
        DateTimeOffset? now = DateTimeOffset.UtcNow;
        await using var tx = await db.Database.BeginTransactionAsync(ct);
        try
        {
            blog.DeletedAt = now;
            await db.Posts.Where(p => p.BlogId == blog.Id).ExecuteUpdateAsync(s => s.SetProperty(p => p.DeletedAt, now), ct);
            await db.SaveChangesAsync(ct);
            await tx.CommitAsync(ct);
        }
        catch (DbUpdateConcurrencyException) { return PreconditionFailed(await CurrentETag(id, ct)); }
        return NoContent();
    }

    private Task<Blog?> FindBlog(Guid id, CancellationToken ct) =>
        db.Blogs.IgnoreQueryFilters().FirstOrDefaultAsync(b => b.PublicId == id, ct);

    private Task<string> CurrentETag(Guid id, CancellationToken ct) =>
        db.Blogs.IgnoreQueryFilters().AsNoTracking().Where(b => b.PublicId == id).Select(b => b.ETag).FirstAsync(ct);

    private static BlogDto ToDto(Blog b) => new() { Id = b.PublicId, Name = b.Name };
}

[Route("api/posts")]
public sealed class PostsController(AppDbContext db) : ApiBaseController
{
    [HttpPost("~/api/blogs/{blogId:guid}/posts")]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create(Guid blogId, [FromBody] PostDto? dto, CancellationToken ct)
    {
        if (dto is null || dto.Id == Guid.Empty || dto.BlogId != blogId || string.IsNullOrWhiteSpace(dto.Title)) return Error(400, "Invalid post");
        var blog = await db.Blogs.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(b => b.PublicId == blogId, ct);
        if (blog is null) return Error(404, "Blog not found");
        if (blog.DeletedAt is not null) return Error(410, "Blog deleted");
        var title = Canon.Normalize(dto.Title);
        var etag = Canon.ETag(new PostRepr(dto.Id, blogId, title));
        var post = new Post { PublicId = dto.Id, BlogId = blog.Id, BlogPublicId = blogId, Title = title, ETag = etag, CreateHash = etag };
        db.Posts.Add(post);
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateException ex) when (IsUniqueViolation(ex))
        {
            db.ChangeTracker.Clear();
            var existing = await db.Posts.IgnoreQueryFilters().AsNoTracking().FirstAsync(p => p.PublicId == dto.Id, ct);
            if (existing.DeletedAt is not null) return Error(410, "Gone");
            if (existing.BlogPublicId != blogId || existing.CreateHash != etag) return Error(409, "Conflict");
            Response.Headers.ETag = existing.ETag;
            return Ok(ToDto(existing));
        }
        Response.Headers.ETag = etag;
        return Created($"/api/posts/{post.PublicId}", ToDto(post));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(PostDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var post = await FindPost(id, ct);
        if (post is null) return Error(404, "Not found");
        if (post.DeletedAt is not null) return Error(410, "Gone");
        await db.Posts.Where(p => p.Id == post.Id).ExecuteUpdateAsync(s => s.SetProperty(p => p.Views, p => p.Views + 1), ct);
        Response.Headers.ETag = post.ETag;
        if (Matches(Request.Headers["If-None-Match"].ToString(), post.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToDto(post));
    }

    [HttpPut("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] PostDto? dto, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (dto is null || dto.Id != id || string.IsNullOrWhiteSpace(dto.Title)) return Error(400, "Invalid post");
        if (string.IsNullOrWhiteSpace(ifMatch)) return Error(428, "If-Match is required");
        var post = await FindPost(id, ct);
        if (post is null) return Error(404, "Not found");
        if (post.DeletedAt is not null) return Error(410, "Gone");
        if (dto.BlogId != post.BlogPublicId) return Error(409, "A post cannot be moved to another blog");
        var title = Canon.Normalize(dto.Title);
        var etag = Canon.ETag(new PostRepr(id, post.BlogPublicId, title));
        if (post.ETag == etag) { Response.Headers.ETag = etag; return NoContent(); }
        if (!Matches(ifMatch, post.ETag)) return PreconditionFailed(post.ETag);
        post.Title = title;
        post.ETag = etag;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return PreconditionFailed(await CurrentETag(id, ct)); }
        Response.Headers.ETag = etag;
        return NoContent();
    }

    [HttpDelete("{id:guid}")]
    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrWhiteSpace(ifMatch)) return Error(428, "If-Match is required");
        var post = await FindPost(id, ct);
        if (post is null || post.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, post.ETag)) return PreconditionFailed(post.ETag);
        post.DeletedAt = DateTimeOffset.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException) { return PreconditionFailed(await CurrentETag(id, ct)); }
        return NoContent();
    }

    private Task<Post?> FindPost(Guid id, CancellationToken ct) =>
        db.Posts.IgnoreQueryFilters().FirstOrDefaultAsync(p => p.PublicId == id, ct);

    private Task<string> CurrentETag(Guid id, CancellationToken ct) =>
        db.Posts.IgnoreQueryFilters().AsNoTracking().Where(p => p.PublicId == id).Select(p => p.ETag).FirstAsync(ct);

    private static PostDto ToDto(Post p) => new() { Id = p.PublicId, BlogId = p.BlogPublicId, Title = p.Title };
}
