[ApiController]
[Route("api/support-tickets")]
public class SupportTicketsController(SupportTicketDbContext db) : ControllerBase
{
    [HttpPost]
    public async Task<ActionResult<TicketDto>> Create([FromBody] TicketRequest req, CancellationToken ct)
    {
        var key = Request.Headers["Idempotency-Key"].ToString();
        if (key.Length > 0)
        {
            var existing = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.CreateKey == key, ct);
            if (existing is not null) return Ok(ToDto(existing));
        }

        var ticket = new Ticket
        {
            Id = Guid.NewGuid(),
            Subject = req.Subject,
            Priority = req.Priority,
            Escalated = req.Escalated,
            Category = req.Category,
            CreateKey = key.Length > 0 ? key : null
        };
        db.Tickets.Add(ticket);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException) when (key.Length > 0)
        {
            // A concurrent retry with the same key won the race.
            db.ChangeTracker.Clear();
            var winner = await db.Tickets.AsNoTracking().FirstAsync(t => t.CreateKey == key, ct);
            return Ok(ToDto(winner));
        }

        Response.Headers.ETag = Etag(ticket.Version);
        return CreatedAtAction(nameof(Get), new { id = ticket.Id }, ToDto(ticket));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<TicketDto>> Get(Guid id, CancellationToken ct)
    {
        var now = DateTime.UtcNow;
        // Atomic counter update; does not bump Version, so it never conflicts with edits.
        var updated = await db.Tickets.Where(t => t.Id == id)
            .ExecuteUpdateAsync(s => s
                .SetProperty(t => t.ViewCount, t => t.ViewCount + 1)
                .SetProperty(t => t.LastViewedAt, now), ct);
        if (updated == 0) return NotFound();

        var ticket = await db.Tickets.AsNoTracking().FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        Response.Headers.ETag = Etag(ticket.Version);
        return ToDto(ticket);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<TicketDto>> Update(Guid id, [FromBody] TicketRequest req, CancellationToken ct)
    {
        var ticket = await db.Tickets.FirstOrDefaultAsync(t => t.Id == id, ct);
        if (ticket is null) return NotFound();

        var ifMatch = Request.Headers.IfMatch.ToString();
        if (ifMatch.Length > 0 && ifMatch != "*" && ifMatch != Etag(ticket.Version))
            return StatusCode(StatusCodes.Status412PreconditionFailed);

        ticket.Subject = req.Subject;
        ticket.Priority = req.Priority;
        ticket.Escalated = req.Escalated;
        ticket.Category = req.Category;
        ticket.Version++;

        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }

        Response.Headers.ETag = Etag(ticket.Version);
        return ToDto(ticket);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var deleted = await db.Tickets.Where(t => t.Id == id).ExecuteDeleteAsync(ct);
        return deleted == 0 ? NotFound() : NoContent();
    }

    private static TicketDto ToDto(Ticket t) => new(t.Id, t.Subject, t.Priority, t.Escalated, t.Category);

    private static string Etag(int version) => $"\"{version}\"";
}
```

Notes on the design:
- **Retries on POST:** send an `Idempotency-Key` header. A retried request with the same key returns the original ticket instead of creating a duplicate.
- **Concurrent edits:** `Version` is an EF concurrency token. A PUT that loses a race returns 409. Clients that send `If-Match` with the ETag from a prior GET get 412 if the ticket changed since they read it. Without `If-Match`, the PUT is last-writer-wins.
- **Server-maintained fields:** `ViewCount` and `LastViewedAt` are updated atomically with `ExecuteUpdate` on GET. This does not bump `Version`, so reads never cause edit conflicts.
- **Responses:** return only `id`, `subject`, `priority`, `escalated`, and `category`. The internal fields are not exposed.
