using System.Security.Cryptography;
using System.Text;
using System.Text.Encodings.Web;
using System.Text.Json;
using System.Globalization;

public sealed record TicketRequest(Guid Id, string? Subject, int Priority, bool Escalated, string? Category)
{
    public bool IsValid => Id != Guid.Empty && !string.IsNullOrWhiteSpace(Subject) && !string.IsNullOrWhiteSpace(Category);

    public TicketRequest Normalize() => this with
    {
        Subject = Subject?.Normalize(NormalizationForm.FormC),
        Category = Category?.Normalize(NormalizationForm.FormC)
    };
}

public sealed record TicketResponse(Guid Id, string Subject, int Priority, bool Escalated, string Category);

public sealed record CanonicalTicket(string Id, string Subject, int Priority, bool Escalated, string Category);

public static class TicketRules
{
    static readonly JsonSerializerOptions CanonOptions = new(JsonSerializerDefaults.Web)
    {
        Encoder = JavaScriptEncoder.UnsafeRelaxedJsonEscaping
    };

    public static string Canonical(TicketRequest request)
    {
        var n = request.Normalize();
        return JsonSerializer.Serialize(
            new CanonicalTicket(n.Id.ToString("D"), n.Subject!, n.Priority, n.Escalated, n.Category!),
            CanonOptions);
    }

    public static string ETagOf(string canonicalJson) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonicalJson)))
            .TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static string Hash(TicketRequest request) => ETagOf(Canonical(request));
}
