        catch (DbUpdateException ex) when (ex.InnerException is SqliteException { SqliteExtendedErrorCode: 2067 })
        {
            db.ChangeTracker.Clear();
            var existing = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == n.Id, ct);
            if (existing is null) return Fail(409, "Conflict.");
            if (existing.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
            if (existing.CreateHash != hash) return Fail(409, "Id already exists with different content.");
            Response.Headers["ETag"] = existing.ETag;
            return Ok(ToResponse(existing));
        }
        Response.Headers["ETag"] = hash;
        return Created($"/api/support-tickets/{n.Id}", ToResponse(t));
    }

    [HttpGet("{id:guid}")]
