            .FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Fail(404, "Ticket not found.");
        if (t.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
        Response.Headers["ETag"] = t.ETag;
        await db.Tickets.Where(x => x.PublicId == id && x.DeletedAt == null)
            .ExecuteUpdateAsync(s => s
                .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                .SetProperty(x => x.LastViewedAt, DateTime.UtcNow), ct);
        if (Matches(Request.Headers["If-None-Match"].ToString(), t.ETag)) return StatusCode(StatusCodes.Status304NotModified);
        return Ok(ToResponse(t));
