    public async Task<IActionResult> Put(Guid id, [FromBody] TicketRequest? body, CancellationToken ct)
    {
        if (body is null || !body.IsValid || body.Id != id) return Fail(400, "Invalid ticket or id mismatch.");
        var ifMatch = Request.Headers["If-Match"].ToString();
        if (ifMatch.Length == 0) return Fail(428, "If-Match header is required.");
        var n = body.Normalize();
        var hash = TicketRules.Hash(n);
        var t = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null) return Fail(404, "Ticket not found.");
        if (t.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
        if (t.ETag == hash) return NoContentWithTag(hash);
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);
        t.Subject = n.Subject!;
        t.Priority = n.Priority;
        t.Escalated = n.Escalated;
        t.Category = n.Category!;
        t.ETag = hash;
