        {
            db.ChangeTracker.Clear();
            var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return Fail(404, "Ticket not found.");
            if (cur.DeletedAt is not null) return Fail(410, "Ticket was deleted.");
            if (cur.ETag == hash) return NoContentWithTag(hash);
            return Precondition(cur.ETag);
