    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var ifMatch = Request.Headers["If-Match"].ToString();
        if (ifMatch.Length == 0) return Fail(428, "If-Match header is required.");
        var t = await db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (t is null || t.DeletedAt is not null) return NoContent();
        if (!Matches(ifMatch, t.ETag)) return Precondition(t.ETag);
        t.DeletedAt = DateTime.UtcNow;
        t.ETag = Guid.NewGuid().ToString("N");
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            return Precondition(cur.ETag);
        }
        return NoContent();
    }

    static TicketResponse ToResponse(Ticket t) =>
        new(t.PublicId, t.Subject, t.Priority, t.Escalated, t.Category);

    static bool Matches(string header, string etag) =>
        header.Split(',').Select(v => v.Trim()).Any(v => v == "*" || v == etag);

    IActionResult Fail(int status, string title) =>
        new ObjectResult(new ProblemDetails { Status = status, Title = title })
        {
            StatusCode = status,
            ContentType = "application/problem+json"
        };

    IActionResult Precondition(string etag)
    {
        Response.Headers["ETag"] = etag;
        return Fail(412, "Precondition failed.");
    }

    IActionResult NoContentWithTag(string etag)
    {
        Response.Headers["ETag"] = etag;
        return NoContent();
    }
}
```

Notes on the design:

- **Create** inserts first and classifies the SQLite unique violation (extended code 2067). It then returns 410 for a deleted item, 200 for a replay (matched against the immutable `CreateHash`), or 409 otherwise.
- **Concurrency** uses `ETag` as the EF concurrency token. A racing writer fails the `WHERE ETag = …` check, which becomes 412 (or 410/404/204 when the reload shows that the state already matches). Delete rotates the ETag, so stale writers, including PUT, fail after a delete.
- **View counting** uses `ExecuteUpdateAsync`, so `ViewCount` and `LastViewedAt` are not concurrency tokens and do not affect the ETag.
- **Canonical JSON** is produced by serializing a fixed-order record with web camelCase options after NFC normalization. The ETag is the quoted unpadded base64url SHA-256 of that string.
- **Unverified points:** the `Consumes` attribute on PUT is fully qualified and may be unnecessary, and I did not check the OpenAPI output against the real behavior. Please compile and run it against TestServer before relying on it.

