        if (shipment is null) return NotFound();

        var target = await db.Depots.FirstOrDefaultAsync(d => d.Id == request.WarehouseId, ct);
        if (target is null) return BadRequest(new ValidationProblemDetails(
            new Dictionary<string, string[]> { ["warehouseId"] = ["Warehouse does not exist."] }));

        var previousWarehouseId = shipment.WarehouseId;
        shipment.WarehouseId = request.WarehouseId;
        shipment.Reference = request.Reference;
        shipment.WeightKg = request.WeightKg;
        shipment.Fragile = request.Fragile;

        var now = DateTime.UtcNow;
        target.LastAuditAt = now;
        if (previousWarehouseId != request.WarehouseId)
        {
            var previous = await db.Depots.FirstOrDefaultAsync(d => d.Id == previousWarehouseId, ct);
            if (previous is not null) previous.LastAuditAt = now;
        }

        await db.SaveChangesAsync(ct);
        return ToResponse(shipment);
