        var depot = await db.Depots.FirstOrDefaultAsync(d => d.Id == shipment.WarehouseId, ct);
        if (depot is not null) depot.LastAuditAt = DateTime.UtcNow;

        db.Consignments.Remove(shipment);
        await db.SaveChangesAsync(ct);
        return NoContent();
    }

    private static ShipmentResponse ToResponse(Consignment c) =>
        new(c.Id, c.WarehouseId, c.Reference, c.WeightKg, c.Fragile);
