using System;
using System.ComponentModel.DataAnnotations;
using System.Collections.Generic;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.EntityFrameworkCore;
using Microsoft.Extensions.DependencyInjection;

namespace WarehouseApi;

public abstract class Entity
{
    public Guid Id { get; set; }

    // Changes on every write. Exposed as the ETag and checked by If-Match for optimistic concurrency.
    public string Stamp { get; set; } = Guid.NewGuid().ToString("N");
}

public class Depot : Entity
{
    public string Code { get; set; } = "";
    public int CapacityCubicMeters { get; set; }
    public DateTime? LastAuditAt { get; set; }
    public List<Consignment> Consignments { get; set; } = new();
}

public class Consignment : Entity
{
    public Guid WarehouseId { get; set; }
    public Depot? Warehouse { get; set; }
    public string Reference { get; set; } = "";
    public decimal WeightKg { get; set; }
    public bool Fragile { get; set; }
    public int DownloadCount { get; set; }
}

public class AppDbContext(DbContextOptions<AppDbContext> options) : DbContext(options)
{
    public DbSet<Depot> Depots => Set<Depot>();
    public DbSet<Consignment> Consignments => Set<Consignment>();

    protected override void OnModelCreating(ModelBuilder b)
    {
        b.Entity<Depot>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Code).IsRequired();
            e.Property(x => x.Stamp).IsConcurrencyToken().HasMaxLength(32);
            e.HasMany(x => x.Consignments).WithOne(x => x.Warehouse)
                .HasForeignKey(x => x.WarehouseId).OnDelete(DeleteBehavior.Cascade);
        });

        b.Entity<Consignment>(e =>
        {
            e.HasKey(x => x.Id);
            e.Property(x => x.Reference).IsRequired();
            e.Property(x => x.WeightKg).HasPrecision(18, 3);
            e.Property(x => x.Stamp).IsConcurrencyToken().HasMaxLength(32);
        });
    }

    public override Task<int> SaveChangesAsync(CancellationToken ct = default)
    {
        var now = DateTime.UtcNow;
        foreach (var entry in ChangeTracker.Entries<Entity>())
        {
            if (entry.State is not (EntityState.Added or EntityState.Modified)) continue;
            entry.Entity.Stamp = Guid.NewGuid().ToString("N");
            if (entry.Entity is Depot depot) depot.LastAuditAt = now;
        }
        return base.SaveChangesAsync(ct);
    }
}

