namespace WarehouseApi;

public static class Concurrency
{
    public static bool IfMatchFails(HttpRequest request, Entity e) =>
        request.Headers.ContainsKey("If-Match") && (string?)request.Headers["If-Match"] != $"\"{e.Stamp}\"";
}

[ApiController]
[Route("api/warehouses")]
