        db.Depots.Add(depot);
        await db.SaveChangesAsync(ct);
        Response.Headers.ETag = $"\"{depot.Stamp}\"";
        return CreatedAtAction(nameof(Get), new { id = depot.Id }, WarehouseResponse.From(depot));
    }

    [HttpGet("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Get(Guid id, CancellationToken ct)
    {
        var depot = await db.Depots.AsNoTracking().FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null) return NotFound();
        Response.Headers.ETag = $"\"{depot.Stamp}\"";
        return WarehouseResponse.From(depot);
    }

    [HttpPut("{id:guid}")]
    public async Task<ActionResult<WarehouseResponse>> Update(Guid id, WarehouseRequest body, CancellationToken ct)
    {
        var depot = await db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null) return NotFound();
        if (Concurrency.IfMatchFails(Request, depot)) return StatusCode(StatusCodes.Status412PreconditionFailed);

        depot.Code = body.Code;
        depot.CapacityCubicMeters = body.CapacityCubicMeters;
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        Response.Headers.ETag = $"\"{depot.Stamp}\"";
        return WarehouseResponse.From(depot);
    }

    [HttpDelete("{id:guid}")]
    public async Task<IActionResult> Delete(Guid id, CancellationToken ct)
    {
        var depot = await db.Depots.FirstOrDefaultAsync(d => d.Id == id, ct);
        if (depot is null) return NoContent();
        db.Depots.Remove(depot);
        try
        {
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateConcurrencyException)
        {
            return Conflict();
        }
        return NoContent();
    }
