using System.Globalization;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;

public static class Api
{
    static string Js(string s) => JsonSerializer.Serialize(s.Normalize(NormalizationForm.FormC));
    static string Num(decimal d) => d.ToString("0.############################", CultureInfo.InvariantCulture);

    public static string WarehouseCanon(Guid id, string code, int capacity) =>
        $"{{\"id\":\"{id:D}\",\"code\":{Js(code)},\"capacityCubicMeters\":{capacity}}}";

    public static string ShipmentCanon(Guid id, Guid warehouseId, string reference, decimal weightKg, bool fragile) =>
        $"{{\"id\":\"{id:D}\",\"warehouseId\":\"{warehouseId:D}\",\"reference\":{Js(reference)},\"weightKg\":{Num(weightKg)},\"fragile\":{(fragile ? "true" : "false")}}}";

    public static string ETag(string canonical) =>
        "\"" + Convert.ToBase64String(SHA256.HashData(Encoding.UTF8.GetBytes(canonical))).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";

    public static bool Matches(string header, string etag) =>
        header.Split(',').Any(t => { var v = t.Trim(); return v == "*" || v == etag; });

    public static ObjectResult Problem(int status, string title)
    {
        var r = new ObjectResult(new ProblemDetails { Status = status, Title = title }) { StatusCode = status };
        r.ContentTypes.Add("application/problem+json");
        return r;
    }

    public static bool IsUnique(DbUpdateException ex) => ex.InnerException is SqliteException { SqliteErrorCode: 19 };
}
