public class WarehousesController(WarehouseDbContext db) : ControllerBase
{
    [HttpPost]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status201Created)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Create([FromBody] WarehouseDto? body, CancellationToken ct)
    {
        if (body is null || body.Id == Guid.Empty || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Api.Problem(400, "Invalid warehouse.");
        var code = body.Code.Normalize(NormalizationForm.FormC);
        var etag = Api.ETag(Api.WarehouseCanon(body.Id, code, body.CapacityCubicMeters));
        var depot = new Depot { PublicId = body.Id, Code = code, CapacityCubicMeters = body.CapacityCubicMeters, ETag = etag, CreateHash = etag, LastAuditAt = DateTime.UtcNow };
        try
        {
            db.Depots.Add(depot);
            await db.SaveChangesAsync(ct);
        }
        catch (DbUpdateException ex) when (Api.IsUnique(ex))
        {
            db.ChangeTracker.Clear();
            var o = await db.Depots.IgnoreQueryFilters().AsNoTracking().SingleAsync(d => d.PublicId == body.Id, ct);
            if (o.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
            if (o.CreateHash != etag) return Api.Problem(409, "Id already exists with different content.");
            Response.Headers["Location"] = $"/api/warehouses/{o.PublicId:D}";
            Response.Headers["ETag"] = o.ETag;
            return Ok(ToDto(o));
        }
        Response.Headers["Location"] = $"/api/warehouses/{depot.PublicId:D}";
        Response.Headers["ETag"] = etag;
        return StatusCode(StatusCodes.Status201Created, ToDto(depot));
    }

    [HttpGet("{id:guid}")]
    [ProducesResponseType(typeof(WarehouseDto), StatusCodes.Status200OK)]
    [ProducesResponseType(StatusCodes.Status304NotModified)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    public async Task<IActionResult> Get(Guid id, CancellationToken ct)
    {
        var d = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Api.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
        Response.Headers["ETag"] = d.ETag;
