    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Put(Guid id, [FromBody] WarehouseDto? body, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (body is null || body.Id != id || string.IsNullOrWhiteSpace(body.Code) || body.CapacityCubicMeters < 0)
            return Api.Problem(400, "Invalid warehouse.");
        if (string.IsNullOrEmpty(ifMatch)) return Api.Problem(428, "If-Match header is required.");
        var code = body.Code.Normalize(NormalizationForm.FormC);
        var etag = Api.ETag(Api.WarehouseCanon(id, code, body.CapacityCubicMeters));
        var d = await db.Depots.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null) return Api.Problem(404, "Warehouse not found.");
        if (d.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
        Response.Headers["ETag"] = d.ETag;
        if (d.ETag == etag) return NoContent();
        if (!Api.Matches(ifMatch, d.ETag)) return Api.Problem(412, "ETag mismatch.");
        d.Code = code; d.CapacityCubicMeters = body.CapacityCubicMeters; d.ETag = etag; d.LastAuditAt = DateTime.UtcNow;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null) return Api.Problem(404, "Warehouse not found.");
            if (cur.DeletedAt is not null) return Api.Problem(410, "Warehouse was deleted.");
            Response.Headers["ETag"] = cur.ETag;
            return cur.ETag == etag ? NoContent() : Api.Problem(412, "ETag mismatch.");
        }
        Response.Headers["ETag"] = etag;
        return NoContent();
    }

