    [ProducesResponseType(StatusCodes.Status204NoContent)]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, "application/problem+json")]
    [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, "application/problem+json")]
    public async Task<IActionResult> Delete(Guid id, [FromHeader(Name = "If-Match"), Required] string? ifMatch, CancellationToken ct)
    {
        if (string.IsNullOrEmpty(ifMatch)) return Api.Problem(428, "If-Match header is required.");
        var d = await db.Depots.IgnoreQueryFilters().Include(x => x.Consignments).FirstOrDefaultAsync(x => x.PublicId == id, ct);
        if (d is null || d.DeletedAt is not null) return NoContent();
        if (!Api.Matches(ifMatch, d.ETag))
        {
            Response.Headers["ETag"] = d.ETag;
            return Api.Problem(412, "ETag mismatch.");
        }
        var now = DateTime.UtcNow;
        d.DeletedAt = now; d.LastAuditAt = now;
        foreach (var c in d.Consignments.Where(c => c.DeletedAt is null)) c.DeletedAt = now;
        try { await db.SaveChangesAsync(ct); }
        catch (DbUpdateConcurrencyException)
        {
            db.ChangeTracker.Clear();
            var cur = await db.Depots.IgnoreQueryFilters().AsNoTracking().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (cur is null || cur.DeletedAt is not null) return NoContent();
            Response.Headers["ETag"] = cur.ETag;
            return Api.Problem(412, "ETag mismatch.");
        }
        return NoContent();
    }

    static WarehouseDto ToDto(Depot d) => new(d.PublicId, d.Code, d.CapacityCubicMeters);
}

