public static class Canon
{
    public static string Norm(string s) => s.Normalize(NormalizationForm.FormC);
    static string Str(string s) => JsonSerializer.Serialize(Norm(s));
    static string G(Guid g) => "\"" + g.ToString("D").ToLowerInvariant() + "\"";

    public static string Blog(Guid id, string name) => Hash("{\"id\":" + G(id) + ",\"name\":" + Str(name) + "}");
    public static string Post(Guid id, Guid blogId, string title) =>
        Hash("{\"id\":" + G(id) + ",\"blogId\":" + G(blogId) + ",\"title\":" + Str(title) + "}");

    static string Hash(string json)
    {
        var h = SHA256.HashData(Encoding.UTF8.GetBytes(json));
        return "\"" + Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static bool Matches(string? header, string etag)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var raw in header.Split(','))
        {
            var t = raw.Trim();
            if (t == "*") return true;
            if (t.StartsWith("W/", StringComparison.Ordinal)) t = t.Substring(2);
            if (t.Trim('"') == etag.Trim('"')) return true;
        }
        return false;
    }
}

