- **Retried POST:** The ID comes from the body `id` if the client sends one. Otherwise it comes from a GUID derived from an `Idempotency-Key` header, or is freshly generated. A retry with the same ID and the same content returns 201 with the existing ticket instead of creating a duplicate. A duplicate ID with different content returns 409. Two simultaneous inserts with the same ID are caught as a `DbUpdateException` and handled the same way.
- **Concurrent edits:**
  - **Updates:** `PUT` uses a single `ExecuteUpdate`, so concurrent writers can't throw and no stale entity is overwritten. The last write wins.
  - **View tracking:** `ViewCount` and `LastViewedAt` are updated atomically on each `GET`, so concurrent views aren't lost. The `PUT` never touches those two fields.
- **Retried DELETE:** The first call returns 204. A repeat returns 404, since the ticket is gone.

```csharp
using System;
using System.Collections.Generic;
using System.ComponentModel.DataAnnotations;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using System.Threading;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Http;
using Microsoft.AspNetCore.Mvc;
using Microsoft.Data.Sqlite;
using Microsoft.EntityFrameworkCore;
using Microsoft.EntityFrameworkCore.Metadata;
using Microsoft.Extensions.DependencyInjection;

namespace SupportTickets
{
    public class Ticket
    {
        public int Id { get; set; }
        public Guid PublicId { get; set; }
        public string Subject { get; set; } = string.Empty;
        public int Priority { get; set; }
        public bool Escalated { get; set; }
        public string Category { get; set; } = string.Empty;
        public string ETag { get; set; } = string.Empty;
        public string CreateHash { get; set; } = string.Empty;
        public DateTime? DeletedAt { get; set; }
        public int ViewCount { get; set; }
        public DateTime? LastViewedAt { get; set; }
    }

    public class AppDbContext : DbContext
    {
        public AppDbContext(DbContextOptions<AppDbContext> options) : base(options) { }

        public DbSet<Ticket> Tickets => Set<Ticket>();

        protected override void OnModelCreating(ModelBuilder modelBuilder)
        {
            modelBuilder.Entity<Ticket>(b =>
            {
                b.HasKey(t => t.Id);
                b.Property(t => t.Id).ValueGeneratedOnAdd();
                b.HasIndex(t => t.PublicId).IsUnique();
                b.Property(t => t.PublicId).Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
                b.Property(t => t.Subject).IsRequired();
                b.Property(t => t.Category).IsRequired();
                b.Property(t => t.ETag).IsRequired().IsConcurrencyToken();
                b.Property(t => t.CreateHash).IsRequired().Metadata.SetAfterSaveBehavior(PropertySaveBehavior.Throw);
                b.Property(t => t.DeletedAt);
                b.Property(t => t.ViewCount);
                b.Property(t => t.LastViewedAt);
                b.HasQueryFilter(t => t.DeletedAt == null);
            });
        }
    }

    public static class AppSetup
    {
        public static void ConfigureServices(IServiceCollection services, string sqliteConnectionString)
        {
            services.AddDbContext<AppDbContext>(o => o.UseSqlite(sqliteConnectionString));
        }
    }

    public class TicketRequest
    {
        public Guid? Id { get; set; }
        public string? Subject { get; set; }
        public int? Priority { get; set; }
        public bool? Escalated { get; set; }
        public string? Category { get; set; }
    }

    public class TicketResponse
    {
        public Guid Id { get; set; }
        public string Subject { get; set; } = string.Empty;
        public int Priority { get; set; }
        public bool Escalated { get; set; }
        public string Category { get; set; } = string.Empty;
    }

    public static class ETagHelper
    {
        public static string Normalize(string s) => s.Normalize(NormalizationForm.FormC);

        public static string Compute(Guid id, string subject, int priority, bool escalated, string category)
        {
            using var ms = new System.IO.MemoryStream();
            using (var w = new Utf8JsonWriter(ms))
            {
                w.WriteStartObject();
                w.WriteString("id", id.ToString("D").ToLowerInvariant());
                w.WriteString("subject", Normalize(subject));
                w.WriteNumber("priority", priority);
                w.WriteBoolean("escalated", escalated);
                w.WriteString("category", Normalize(category));
                w.WriteEndObject();
            }
            var hash = SHA256.HashData(ms.ToArray());
            var b64 = Convert.ToBase64String(hash).Replace('+', '-').Replace('/', '_').TrimEnd('=');
            return "\"" + b64 + "\"";
        }

        public static bool Matches(string? header, string etag)
        {
            if (string.IsNullOrWhiteSpace(header)) return false;
            foreach (var part in header.Split(','))
            {
                var p = part.Trim();
                if (p == "*") return true;
                if (p.StartsWith("W/", StringComparison.Ordinal)) p = p.Substring(2);
                if (p == etag) return true;
            }
            return false;
        }
    }

    [Route("api/support-tickets")]
    public class SupportTicketsController : ControllerBase
    {
        private const string Problem_ = "application/problem+json";
        private readonly AppDbContext _db;

        public SupportTicketsController(AppDbContext db)
        {
            _db = db;
        }

        private ObjectResult Err(int status, string title)
        {
            var pd = new ProblemDetails { Status = status, Title = title };
            return new ObjectResult(pd) { StatusCode = status, ContentTypes = { Problem_ } };
        }

        private static TicketResponse ToResponse(Ticket t) => new TicketResponse
        {
            Id = t.PublicId,
            Subject = t.Subject,
            Priority = t.Priority,
            Escalated = t.Escalated,
            Category = t.Category
        };

        private void SetETag(string etag) => Response.Headers["ETag"] = etag;

        private static bool Valid(TicketRequest? r) =>
            r != null && r.Id.HasValue && r.Id.Value != Guid.Empty && !string.IsNullOrWhiteSpace(r.Subject)
            && r.Priority.HasValue && r.Escalated.HasValue && r.Category != null;

        private static bool IsUniqueViolation(DbUpdateException ex) =>
            ex.InnerException is SqliteException { SqliteErrorCode: 19 };

        [HttpPost]
        [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status201Created)]
        [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status409Conflict, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, Problem_)]
        public async Task<IActionResult> Create([FromBody] TicketRequest? request, CancellationToken ct)
        {
            if (!Valid(request)) return Err(400, "Invalid request body.");
            var id = request!.Id!.Value;
            var etag = ETagHelper.Compute(id, request.Subject!, request.Priority!.Value, request.Escalated!.Value, request.Category!);
            var entity = new Ticket
            {
                PublicId = id,
                Subject = ETagHelper.Normalize(request.Subject!),
                Priority = request.Priority.Value,
                Escalated = request.Escalated.Value,
                Category = ETagHelper.Normalize(request.Category!),
                ETag = etag,
                CreateHash = etag
            };
            _db.Tickets.Add(entity);
            try
            {
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateException ex) when (IsUniqueViolation(ex))
            {
                _db.Entry(entity).State = EntityState.Detached;
                var existing = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                    .FirstOrDefaultAsync(t => t.PublicId == id, ct);
                if (existing == null) return Err(409, "Conflict creating ticket.");
                if (existing.DeletedAt != null) return Err(410, "Ticket was deleted.");
                if (existing.CreateHash != etag) return Err(409, "Ticket exists with different content.");
                SetETag(existing.ETag);
                return Ok(ToResponse(existing));
            }
            SetETag(entity.ETag);
            return Created("/api/support-tickets/" + id.ToString("D"), ToResponse(entity));
        }

        [HttpGet("{id:guid}")]
        [ProducesResponseType(typeof(TicketResponse), StatusCodes.Status200OK)]
        [ProducesResponseType(StatusCodes.Status304NotModified)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, Problem_)]
        public async Task<IActionResult> Get(Guid id, CancellationToken ct)
        {
            var t = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                .FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (t == null) return Err(404, "Ticket not found.");
            if (t.DeletedAt != null) return Err(410, "Ticket was deleted.");

            var now = DateTime.UtcNow;
            await _db.Tickets.Where(x => x.PublicId == id && x.DeletedAt == null)
                .ExecuteUpdateAsync(s => s
                    .SetProperty(x => x.ViewCount, x => x.ViewCount + 1)
                    .SetProperty(x => x.LastViewedAt, now), ct);

            SetETag(t.ETag);
            if (ETagHelper.Matches(Request.Headers["If-None-Match"].ToString(), t.ETag))
                return StatusCode(StatusCodes.Status304NotModified);
            return Ok(ToResponse(t));
        }

        [HttpPut("{id:guid}")]
        [ProducesResponseType(StatusCodes.Status204NoContent)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status400BadRequest, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status404NotFound, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status410Gone, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, Problem_)]
        public async Task<IActionResult> Put(Guid id, [FromBody] TicketRequest? request,
            [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
        {
            if (!Valid(request) || request!.Id!.Value != id) return Err(400, "Invalid request body.");
            if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match header is required.");

            var newEtag = ETagHelper.Compute(id, request.Subject!, request.Priority!.Value, request.Escalated!.Value, request.Category!);
            var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (t == null) return Err(404, "Ticket not found.");
            if (t.DeletedAt != null) return Err(410, "Ticket was deleted.");

            if (t.ETag == newEtag)
            {
                SetETag(t.ETag);
                return NoContent();
            }
            if (!ETagHelper.Matches(ifMatch, t.ETag))
            {
                SetETag(t.ETag);
                return Err(412, "If-Match does not match the current ETag.");
            }

            t.Subject = ETagHelper.Normalize(request.Subject!);
            t.Priority = request.Priority.Value;
            t.Escalated = request.Escalated.Value;
            t.Category = ETagHelper.Normalize(request.Category!);
            t.ETag = newEtag;
            try
            {
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.ChangeTracker.Clear();
                var cur = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                    .FirstOrDefaultAsync(x => x.PublicId == id, ct);
                if (cur == null) return Err(404, "Ticket not found.");
                if (cur.DeletedAt != null) return Err(410, "Ticket was deleted.");
                SetETag(cur.ETag);
                if (cur.ETag == newEtag) return NoContent();
                return Err(412, "Ticket was modified concurrently.");
            }
            SetETag(newEtag);
            return NoContent();
        }

        [HttpDelete("{id:guid}")]
        [ProducesResponseType(StatusCodes.Status204NoContent)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status412PreconditionFailed, Problem_)]
        [ProducesResponseType(typeof(ProblemDetails), StatusCodes.Status428PreconditionRequired, Problem_)]
        public async Task<IActionResult> Delete(Guid id,
            [FromHeader(Name = "If-Match")][Required] string? ifMatch, CancellationToken ct)
        {
            if (string.IsNullOrWhiteSpace(ifMatch)) return Err(428, "If-Match header is required.");

            var t = await _db.Tickets.IgnoreQueryFilters().FirstOrDefaultAsync(x => x.PublicId == id, ct);
            if (t == null || t.DeletedAt != null) return NoContent();
            if (!ETagHelper.Matches(ifMatch, t.ETag))
            {
                SetETag(t.ETag);
                return Err(412, "If-Match does not match the current ETag.");
            }

            t.DeletedAt = DateTime.UtcNow;
            try
            {
                await _db.SaveChangesAsync(ct);
            }
            catch (DbUpdateConcurrencyException)
            {
                _db.ChangeTracker.Clear();
                var cur = await _db.Tickets.IgnoreQueryFilters().AsNoTracking()
                    .FirstOrDefaultAsync(x => x.PublicId == id, ct);
                if (cur == null || cur.DeletedAt != null) return NoContent();
                SetETag(cur.ETag);
                return Err(412, "Ticket was modified concurrently.");
            }
            return NoContent();
        }
    }
}
