public static class Canon
{
    public static string Norm(string s) => s.Normalize(NormalizationForm.FormC);

    public static string Dec(decimal d)
    {
        if (d == 0) return "0";
        var s = d.ToString(CultureInfo.InvariantCulture);
        if (s.Contains('.')) s = s.TrimEnd('0').TrimEnd('.');
        return s;
    }

    static string Hash(Action<Utf8JsonWriter> write)
    {
        using var ms = new MemoryStream();
        using (var w = new Utf8JsonWriter(ms))
        {
            w.WriteStartObject();
            write(w);
            w.WriteEndObject();
        }
        var h = SHA256.HashData(ms.ToArray());
        return "\"" + Convert.ToBase64String(h).TrimEnd('=').Replace('+', '-').Replace('/', '_') + "\"";
    }

    public static string Depot(Guid id, string code, int cap) => Hash(w =>
    {
        w.WriteString("id", id.ToString("D").ToLowerInvariant());
        w.WriteString("code", code);
        w.WriteNumber("capacityCubicMeters", cap);
    });

    public static string Consignment(Guid id, Guid wid, string reference, decimal weight, bool fragile) => Hash(w =>
    {
        w.WriteString("id", id.ToString("D").ToLowerInvariant());
        w.WriteString("warehouseId", wid.ToString("D").ToLowerInvariant());
        w.WriteString("reference", reference);
        w.WritePropertyName("weightKg");
        w.WriteRawValue(Dec(weight));
        w.WriteBoolean("fragile", fragile);
    });

    public static bool Matches(string? header, string etag, bool allowStar)
    {
        if (string.IsNullOrWhiteSpace(header)) return false;
        foreach (var part in header.Split(','))
        {
            var p = part.Trim();
            if (p == "*") { if (allowStar) return true; continue; }
            if (p.StartsWith("W/", StringComparison.Ordinal)) p = p.Substring(2);
            if (p == etag) return true;
        }
        return false;
    }
}

