        if (b == null || b.Id == null || b.Id == Guid.Empty || b.WarehouseId == null || b.WarehouseId == Guid.Empty
            || string.IsNullOrWhiteSpace(b.Reference) || b.WeightKg == null || b.WeightKg < 0 || b.Fragile == null) return false;
        id = b.Id.Value; wid = b.WarehouseId.Value; reference = Canon.Norm(b.Reference);
        weight = b.WeightKg.Value; fragile = b.Fragile.Value;
        return true;
    }
